def max_rect(I,v=6):
    H,W=len(I),len(I[0]); res=[]; seen=set()
    for i in range(H-1):
        for j in range(W-1):
            if I[i][j]==v and I[i][j+1]==v and I[i+1][j]==v and I[i+1][j+1]==v and (i,j) not in seen:
                q=[(i,j)]; seen.add((i,j)); cells={(i,j)}
                while q:
                    y,x=q.pop()
                    for dy,dx in ((0,1),(1,0)):
                        ny,nx=y+dy,x+dx
                        if ny<H and nx<W and I[ny][nx]==v and (ny,nx) not in seen:
                            seen.add((ny,nx)); cells.add((ny,nx)); q.append((ny,nx))
                # bounding box area minus 4 == extras
                rs=[r for r,_ in cells]; cs=[c for _,c in cells]
                h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
                res.append((h,w,len(cells)))
    return res
